626	// --- element picker: click an element in the live preview to grab its selector,
627	// same idea as devtools' inspect tool. If you land on an <img>/<svg>/<picture>
628	// itself, it climbs to the parent wrapper instead, since the selector this tool
629	// wants is the *container* whose <img> children get filled in.
630	const picker = { active: false, doc: null, hovered: null, tagEl: null, btn: null, targetInput: null };
631	
632	function pickerTargetFor(el) {
633	  if (!el) return el;
634	  // For the image-slot picker, landing on the <img>/<svg>/<picture> itself should
635	  // climb to its parent wrapper - that's the "container" the fill logic wants. Every
636	  // other picker (e.g. delete) wants exactly the element under the cursor.
637	  if (picker.targetInput && picker.targetInput.id === 'imgSelector') {
638	    const media = el.closest('img, svg, picture');
639	    if (media) return media.parentElement || media;
640	  }
641	  return el;
642	}
643	
644	// Page-builder markup (Colibri, Elementor, ...) puts generic utility classes first
645	// (d-flex, position-relative, align-items-center - shared by dozens of unrelated
646	// elements) and the actually-unique per-element class last (style-204, style-local-
647	// 60-c2, ...). A naive "first 2 classes" pick grabs the generic ones and produces a
648	// selector that silently matches many elements at once - classes containing a digit
649	// are a solid proxy for "auto-generated, probably unique", so prefer those first.
650	function _classSpecificityRank(c) {
651	  return /\d/.test(c) ? 0 : 1;
652	}
653	
654	function cssPathFor(el) {
655	  if (!el || el.nodeType !== 1) return '';
656	  if (el.id) return '#' + CSS.escape(el.id);
657	  const parts = [];
658	  let node = el;
659	  while (node && node.nodeType === 1 && !['html', 'body'].includes(node.tagName.toLowerCase())) {
660	    let part = node.tagName.toLowerCase();
661	    const cls = (typeof node.className === 'string' ? node.className : '')
662	      .trim().split(/\s+/).filter(Boolean).filter(c => !c.startsWith('site-studio'))
663	      .sort((a, b) => _classSpecificityRank(a) - _classSpecificityRank(b))
664	      .slice(0, 2);
665	    if (cls.length) part += '.' + cls.map(c => CSS.escape(c)).join('.');
666	    const parent = node.parentElement;
667	    if (parent) {
668	      const sameTag = Array.from(parent.children).filter(s => s.tagName === node.tagName);
669	      if (sameTag.length > 1) part += `:nth-of-type(${sameTag.indexOf(node) + 1})`;
670	    }
671	    parts.unshift(part);
672	    if (node.id || parts.length >= 4) break;
673	    node = node.parentElement;
674	  }
675	  return parts.join(' > ');
676	}
677	
678	function paintHighlight(el, color, fill) {
679	  el.style.outline = `2px solid ${color}`;
680	  el.style.outlineOffset = '-2px';
681	  el.style.boxShadow = `inset 0 0 0 9999px ${fill}`;
682	  el.style.transition = 'box-shadow .1s ease';
683	}
684	
685	function clearHighlight(el) {
686	  if (!el) return;
687	  el.style.outline = '';
688	  el.style.outlineOffset = '';
689	  el.style.boxShadow = '';
690	  el.style.transition = '';
691	}
692	
693	function positionTag(el) {
694	  if (!picker.tagEl || !el) return;
695	  const rect = el.getBoundingClientRect();
696	  const selector = cssPathFor(el);
697	  const dims = `${Math.round(rect.width)}×${Math.round(rect.height)}`;
698	  picker.tagEl.textContent = `${selector}  ${dims}`;
699	  const top = rect.top > 24 ? rect.top - 22 : rect.bottom + 4;
700	  picker.tagEl.style.top = Math.max(2, top) + 'px';
701	  picker.tagEl.style.left = Math.max(2, rect.left) + 'px';
702	  picker.tagEl.style.display = 'block';
703	}
704	
705	function onPickerOver(e) {
706	  const el = pickerTargetFor(e.target);
707	  if (picker.hovered === el) return;
708	  if (picker.hovered) clearHighlight(picker.hovered);
709	  picker.hovered = el;
710	  if (el) {
711	    paintHighlight(el, '#1c8a4c', 'rgba(28,138,76,.14)');
712	    positionTag(el);
713	  }
714	}
715	
716	function onPickerClick(e) {
717	  e.preventDefault();
718	  e.stopPropagation();
719	  e.stopImmediatePropagation();
720	  const el = pickerTargetFor(e.target);
721	  if (!el) { stopPicker(); return; }
722	  if (picker.targetInput) {
723	    picker.targetInput.value = cssPathFor(el);
724	    if (picker.targetInput.id === 'imgSelector') updateSelectorMatchInfo();
725	  }
726	  paintHighlight(el, '#7fe0a8', 'rgba(127,224,168,.22)');
727	  if (picker.tagEl) picker.tagEl.style.display = 'none';
728	  stopPickerListeners();
729	  setTimeout(() => { clearHighlight(el); }, 260);
730	}
731	
732	function onPickerKey(e) {
733	  if (e.key === 'Escape') stopPicker();
734	}
