736	function togglePicker(btn) {
737	  if (picker.active) { stopPicker(); return; }
738	  const iframe = document.getElementById('preview');
739	  let doc;
740	  try { doc = iframe.contentDocument; } catch (e) { doc = null; }
741	  if (!doc || !doc.body) { alert('Превью ещё не загружено'); return; }
742	  picker.active = true;
743	  picker.doc = doc;
744	  picker.btn = btn;
745	  picker.targetInput = document.getElementById(btn.dataset.target);
746	
747	  const tag = doc.createElement('div');
748	  tag.id = 'site-studio-picker-tag';
749	  tag.style.cssText = 'position:fixed; z-index:2147483647; display:none; pointer-events:none; ' +
750	    'background:#1c8a4c; color:#fff; font:600 11px/1 Consolas,monospace; padding:4px 7px; ' +
751	    'border-radius:4px; box-shadow:0 2px 8px rgba(0,0,0,.25); white-space:nowrap;';
752	  doc.body.appendChild(tag);
753	  picker.tagEl = tag;
754	
755	  const cursorStyle = doc.createElement('style');
756	  cursorStyle.id = 'site-studio-picker-style';
757	  cursorStyle.textContent = '* { cursor: crosshair !important; }';
758	  doc.head.appendChild(cursorStyle);
759	  picker.cursorStyleEl = cursorStyle;
760	
761	  doc.addEventListener('mouseover', onPickerOver, true);
762	  doc.addEventListener('click', onPickerClick, true);
763	  doc.addEventListener('keydown', onPickerKey, true);
764	
765	  btn.classList.add('picking');
766	  btn.querySelector('.picker-btn-icon').textContent = '✕';
767	  btn.querySelector('.picker-btn-text').textContent = 'Отмена (Esc)';
768	  document.getElementById('pickerBanner').classList.add('show');
769	}
770	
771	function stopPickerListeners() {
772	  const doc = picker.doc;
773	  if (doc) {
774	    doc.removeEventListener('mouseover', onPickerOver, true);
775	    doc.removeEventListener('click', onPickerClick, true);
776	    doc.removeEventListener('keydown', onPickerKey, true);
777	    if (picker.cursorStyleEl) picker.cursorStyleEl.remove();
778	  }
779	  picker.active = false;
780	  if (picker.btn) {
781	    picker.btn.classList.remove('picking');
782	    picker.btn.querySelector('.picker-btn-icon').textContent = '◎';
783	    picker.btn.querySelector('.picker-btn-text').textContent = 'Выбрать на превью';
784	  }
785	  document.getElementById('pickerBanner').classList.remove('show');
786	}
787	
788	function stopPicker() {
789	  if (!picker.active) return;
790	  if (picker.hovered) clearHighlight(picker.hovered);
791	  if (picker.tagEl) { picker.tagEl.remove(); picker.tagEl = null; }
792	  stopPickerListeners();
793	  picker.doc = null;
794	  picker.hovered = null;
795	  picker.btn = null;
796	  picker.targetInput = null;
797	}
