// Wrap everything after each .section-head into a .section-body > .section-body-inner
// so the body can animate its height smoothly (grid 1fr <-> 0fr) instead of snapping
// with display:none. Done in JS to keep the markup of all sections untouched.
function wrapSections() {
  document.querySelectorAll('.section').forEach(sec => {
    if (sec.querySelector(':scope > .section-body')) return;
    const head = sec.querySelector('.section-head');
    if (!head) return;
    const body = document.createElement('div');
    body.className = 'section-body';
    const inner = document.createElement('div');
    inner.className = 'section-body-inner';
    let node = head.nextSibling;
    while (node) { const next = node.nextSibling; inner.appendChild(node); node = next; }
    body.appendChild(inner);
    sec.appendChild(body);
  });
}

