_BRAND_TEXT_ATTRS = ("alt", "title", "aria-label", "placeholder", "content", "value")
_BRAND_SKIP_PARENTS = {"script", "style"}


def replace_brand_text_everywhere(html_path, old_name, new_name):
    """Replace the old owner's brand name with the new one EVERYWHERE it appears as a
    whole word - across every visible text node AND the text-bearing attributes
    (alt/title/aria-label/placeholder/meta content/value) - not just the logo element
    and <title> the way apply_brand_text does. The archived page still carries the
    original company name scattered through headings, footers (©), image alts and og
    meta; this is what makes the restored page read as the new owner's, and matters for
    de-duplication against the original. Case-insensitive, whole-word (so 'Sun' won't
    hit 'Sunday'). Skips <script>/<style> bodies."""
    old_name = (old_name or "").strip()
    new_name = (new_name or "").strip()
    if not old_name:
        raise ValueError("укажи старое имя бренда (что заменить)")
    if not new_name:
        raise ValueError("укажи новое имя бренда")

    pattern = re.compile(r"(?<!\w)" + re.escape(old_name) + r"(?!\w)", re.IGNORECASE)
    soup = _read_soup(html_path)

    text_hits = 0
    for node in soup.find_all(string=True):
        if node.parent is not None and node.parent.name in _BRAND_SKIP_PARENTS:
            continue
        new_val, n = pattern.subn(new_name, str(node))
        if n:
            node.replace_with(new_val)
            text_hits += n

    attr_hits = 0
    for tag in soup.find_all(True):
        for attr in _BRAND_TEXT_ATTRS:
            val = tag.get(attr)
            if isinstance(val, str) and val:
                new_val, n = pattern.subn(new_name, val)
                if n:
                    tag[attr] = new_val
                    attr_hits += n

    if text_hits == 0 and attr_hits == 0:
        raise ValueError(f"'{old_name}' не встречается в тексте или атрибутах страницы")

    _write_soup(html_path, soup)
    return {"text_replacements": text_hits, "attr_replacements": attr_hits}


_VERIFY_META_NAMES = {
    "google-site-verification", "msvalidate.01", "yandex-verification",
    "p:domain_verify", "norton-safeweb-site-verification", "alexaverifyid",
    "facebook-domain-verification", "baidu-site-verification", "wot-verification",
    "shopify-checkout-api-token", "csrf-token",
}
_TRACE_META_NAMES = {"generator", "author", "copyright", "publisher"}
_VERIFY_META_PROPS = {"fb:app_id", "fb:admins", "fb:pages"}
_COPYRIGHT_YEAR_RE = re.compile(r"(©|copyright)\s*\d{4}(?:\s*[-–—]\s*\d{4})?", re.IGNORECASE)


def strip_owner_traces(html_path, update_year=True):
    """Remove the leftover fingerprints of the previous owner that the script-level
    cleanup doesn't touch: search-console / social verification <meta> tags
    (google-site-verification, yandex, bing msvalidate, fb domain verify, pinterest,
    ...), fb:app_id / fb:admins, generator/author/copyright/publisher meta, and any
    GoogleTagManager/Analytics <noscript> fallback still baked in. Optionally bumps the
    year in a '© 20xx' footer to the current year. Returns what it removed."""
    soup = _read_soup(html_path)
    removed = []

    for meta in list(soup.find_all("meta")):
        name = (meta.get("name") or "").strip().lower()
        prop = (meta.get("property") or "").strip().lower()
        if name in _VERIFY_META_NAMES or name in _TRACE_META_NAMES or prop in _VERIFY_META_PROPS:
            removed.append(f'<meta {"property" if prop else "name"}="{prop or name}">')
            meta.decompose()

    for ns in list(soup.find_all("noscript")):
        blob = str(ns)
        if "googletagmanager.com" in blob or "google-analytics.com" in blob:
            removed.append("<noscript> GTM/GA fallback")
            ns.decompose()

    year_updates = 0
    if update_year:
        current = str(datetime.now().year)
        for node in soup.find_all(string=_COPYRIGHT_YEAR_RE):
            if node.parent is not None and node.parent.name in _BRAND_SKIP_PARENTS:
                continue
            new_val, n = _COPYRIGHT_YEAR_RE.subn(lambda m: f"{m.group(1)} {current}", str(node))
            if n:
                node.replace_with(new_val)
                year_updates += n

    _write_soup(html_path, soup)
    return {"removed": removed, "year_updates": year_updates}


def revert_to_backup(html_path, which="auto"):
    """Restore index.html from a backup. Two kinds exist: '.bak' (written by
    clean_wayback_site before a full cleanup = the pre-cleanup original) and
    '.studio-bak' (written before the first site_studio mutation this session). 'auto'
    picks the most recently created one - i.e. the closest previous state, the natural
    'undo last thing' target. The current file is snapshotted to '.pre-revert' first so
    the revert itself is reversible. Only index.html is restored - moved assets and the
    extracted CSS are not rolled back."""
    candidates = {
        "studio-bak": html_path.with_suffix(html_path.suffix + ".studio-bak"),
        "bak": html_path.with_suffix(html_path.suffix + ".bak"),
    }
    existing = {k: p for k, p in candidates.items() if p.is_file()}
    if not existing:
        raise ValueError("бэкапов не найдено (.bak / .studio-bak рядом с index.html нет)")

    if which in existing:
        chosen_key = which
    else:
        chosen_key = max(existing, key=lambda k: existing[k].stat().st_mtime)
    src = existing[chosen_key]

    pre = html_path.with_suffix(html_path.suffix + ".pre-revert")
    shutil.copyfile(html_path, pre)
    shutil.copyfile(src, html_path)
    return {"restored_from": src.name, "prev_saved_as": pre.name}


_PACKAGE_EXCLUDE_SUFFIXES = (".bak", ".studio-bak", ".pre-revert")
_PACKAGE_EXCLUDE_DIRS = {"_wayback_removed", "_unused_removed"}


def package_for_upload(html_path, clean_unused=True, purge_source=False):
    """Assemble an upload-ready zip of the site next to its folder as
    '<folder>_ready.zip', leaving OUT every backup/quarantine artefact (.bak,
    .studio-bak, .pre-revert, *.cleanup-report.txt, _wayback_removed/, _unused_removed/)
    so what lands on the host is just the live site. Optionally runs the unused-asset
    sweep first (so duplicates/leftovers get quarantined and then excluded), and
    optionally purges those same artefacts from the source folder itself (destructive -
    kills the ability to revert afterwards)."""
    site_dir = html_path.parent
    result = {}

    if clean_unused:
        try:
            result["unused_quarantined"] = remove_unused_assets(html_path)
        except Exception as e:  # noqa: BLE001 - packaging shouldn't die on a sweep hiccup
            result["unused_quarantined_error"] = str(e)

    zip_path = site_dir.parent / f"{site_dir.name}_ready.zip"

    def _excluded(path):
        rel_parts = path.relative_to(site_dir).parts
        if any(part in _PACKAGE_EXCLUDE_DIRS for part in rel_parts):
            return True
        if path.suffix.lower() in _PACKAGE_EXCLUDE_SUFFIXES:
            return True
        if path.name.endswith(".cleanup-report.txt") or path.name.endswith("_ready.zip"):
            return True
        return False

    count = 0
    with zipfile.ZipFile(zip_path, "w", zipfile.ZIP_DEFLATED) as zf:
        for p in sorted(site_dir.rglob("*")):
            if p.is_file() and not _excluded(p):
                zf.write(p, p.relative_to(site_dir).as_posix())
                count += 1

    result["zip"] = str(zip_path)
    result["files_zipped"] = count
    result["zip_size"] = zip_path.stat().st_size

    purged = []
    if purge_source:
        for p in list(site_dir.rglob("*")):
            if p.is_file() and (p.suffix.lower() in _PACKAGE_EXCLUDE_SUFFIXES or p.name.endswith(".cleanup-report.txt")):
                try:
                    p.unlink()
                    purged.append(p.relative_to(site_dir).as_posix())
                except OSError:
                    pass
        for d in _PACKAGE_EXCLUDE_DIRS:
            dd = site_dir / d
            if dd.is_dir():
                shutil.rmtree(dd, ignore_errors=True)
                purged.append(d + "/")
    result["purged"] = purged
    return result

