px = img.load()

x0, x1 = 30, 340  # panel text region, exclude number (~20) and chevron (~360)
rows_text = []   # rows containing dark text glyphs
rows_val = []    # mean brightness per row across the region
for y in range(H):
    dark = 0
    s = 0
    for x in range(x0, x1):
        v = px[x, y]
        s += v
        if v < 110:
            dark += 1
    rows_text.append(dark)
    rows_val.append(s / (x1 - x0))

# text bands: consecutive rows with dark pixels
bands = []
in_band = False
for y in range(H):
    if rows_text[y] > 3:
        if not in_band:
            start = y; in_band = True
        end = y
    else:
        if in_band:
            bands.append((start, end)); in_band = False
if in_band:
    bands.append((start, end))

# dividers: rows that are LOCAL minima in brightness (faint line), not in a text band
def in_text(y):
    return any(b0 - 2 <= y <= b1 + 2 for b0, b1 in bands)

bg = sorted(rows_val)[len(rows_val)//2]  # median = panel bg
dividers = []
for y in range(5, H - 5):
    if in_text(y):
