from PIL import Image
img = Image.open(r"C:\Users\Office\AppData\Local\Temp\claude\c--1LETO-cms-webArchive\13d2ad30-cf77-466e-a43e-89d1d71c3ee0\scratchpad\studio_shot.png").convert("L")
W, H = img.size
px = img.load()
x0, x1 = 40, 340
N = x1 - x0

def row_stats(y):
    dark = faint = 0
    for x in range(x0, x1):
        v = px[x, y]
        if v < 110:
            dark += 1
        elif v < 233:          # faint = border tone (bg ~239)
            faint += 1
    return dark, faint

bg = 239
dividers, titles, subtitles = [], [], []
for y in range(H):
    dark, faint = row_stats(y)
    if faint / N > 0.6 and dark < 3:
        dividers.append(y)          # full-width faint line
    elif dark > 20:
        titles.append(y)            # bold dark title row
    elif 3 <= dark <= 20:
        subtitles.append(y)         # ragged faint-gray subtitle text

def collapse(rows, gap=4):
    out = []
    for y in rows:
        if out and y - out[-1][1] <= gap:
            out[-1][1] = y
        else:
            out.append([y, y])
    return out

D = collapse(dividers)
T = collapse(titles, 6)
S = collapse(subtitles, 6)
print("dividers:", [f"{a}-{b}" for a, b in D])
print("titles:  ", [f"{a}-{b}" for a, b in T])
print("subtitles:", [f"{a}-{b}" for a, b in S])

# For sections 03 and 04 (single-line subtitle, clean), compute top vs bottom gap.
def gap_report(title_band):
    ct = (title_band[0] + title_band[1]) / 2
    div_above = max([b for a, b in D if b < title_band[0]], default=None)
    subs_below = [s for s in S if s[0] > title_band[1]]
    div_below = min([a for a, b in D if a > title_band[1]], default=None)
    sub = subs_below[0] if subs_below else None
    if div_above is None or div_below is None or sub is None:
        return None
    top_gap = title_band[0] - div_above          # divider -> title top
    bottom_gap = div_below - sub[1]               # subtitle bottom -> divider
    return dict(title=title_band, top_gap=top_gap, bottom_gap=bottom_gap,
                div_above=div_above, div_below=div_below, subtitle=sub)

for tb in T:
    r = gap_report(tb)
    if r:
        print(r)

